const $=id=>document.getElementById(id),show=(id,value)=>{$(id).hidden=!value;},txt=(id,v)=>{if($(id).textContent!==String(v))$(id).textContent=v;};
const SAVE='santa-cruz-pixel-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=null;try{saved=JSON.parse(localStorage.getItem(SAVE)||'null');}catch{}
const sim=new PixelSimulation({saved,conditions:sea}),sprites=createPixelSprites(),world=createPixelWorld($('world'),{sprites,conditions:sim.conditions}),audio=new PixelAudio();
const keys=new Set(),sources=new ActionSources(),pointers=[];let stick={x:0,y:0},stickDriving=false,menu=null,lastFocus=null,toastTimer=null,lastToastId=0,lastFishState='idle',lastFrame=performance.now(),uiElapsed=0,saveElapsed=0,frames=0,fps=60,fpsTimer=0,reelToggle=false,started=false,castOwner=null,boatPanel='tackle';
const helm=mountHelm($('helm'),{getState:()=>({...sim.state,canOperateHelm:sim.canOperateHelm}),onIdle:()=>{if(sim.state.engine&&!sim.state.waypoint)sim.setThrottle(0);},onFeedback:r=>feedback(r)});
const fishing=mountFishingConsole($('boat-fishing'),{sim,onStopReel:()=>{reelToggle=false;},onFeedback:r=>r?.action==='catch'?openCatch():feedback(r),onMount:value=>{helm.reset();feedback(sim.setRodMount(value));persist();}});
function drawAsset(canvas,asset){if(!asset)return;canvas.width=asset.width;canvas.height=asset.height;canvas.getContext('2d').drawImage(asset,0,0);}
for(const el of document.querySelectorAll('[data-icon]'))drawAsset(el,sprites.icons[el.dataset.icon]);
