const heading=(eyebrow,title,description='')=>`<div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2>${description?`<p class="modal-desc">${description}</p>`:''}`;
const button=(id,label,primary=false)=>`<button id="${id}" class="${primary?'primary':'secondary'}">${label}</button>`;
function openStaff(){
 const s=sim.state;if(!sim.atCounter){feedback(sim.walkTo('counter'));return;}
 const awaiting=s.launchStage==='stored',unpaid=!s.rentalPaid,affordable=s.profile.credits>=BOAT_RENTAL_PRICE;
 const label=awaiting?(unpaid?`付款租船 · ✦ ${BOAT_RENTAL_PRICE}`:'吊艇下水'):'前往登船平台';
 const greeting=unpaid?'小艇还在岸上。付清租金后，我来操作吊臂。':s.launchStage==='lowering'?'正在下放木艇，沿左侧台阶去等候。':'船放稳以后，沿左侧台阶下去。';
 openModal('staff',`<span class="balance">✦ ${s.profile.credits}</span>`+heading('SANTA CRUZ BOAT RENTALS','码头小屋')+`<div class="staff-banner"><canvas id="staff-portrait"></canvas><p><b>值班员 · 码头小屋</b>${greeting}</p></div><div class="rental-ticket"><div><small>小木船 · 本次航程</small><strong>${unpaid?'岸上待租':s.launchStage==='lowering'?'吊艇进行中':'已付款'}</strong></div><span>${unpaid?'✦ '+BOAT_RENTAL_PRICE:'✓'}</span></div><div class="button-row">${button('launch-boat',label,true)}</div><p id="rental-message" class="rental-message" role="status">${unpaid&&!affordable?`还差 ${BOAT_RENTAL_PRICE-s.profile.credits} 潮汐点。`:''}</p><div class="button-row">${button('staff-shop','兑换装备')}${button('staff-trade','兑换鱼获')}${button('staff-restock','免费补给')}</div>`);
 drawAsset($('staff-portrait'),sprites.dockWorker);$('staff-shop').onclick=()=>openGear('shop');$('staff-trade').onclick=()=>{feedback(sim.trade());persist();openStaff();};$('staff-restock').onclick=()=>feedback(sim.restock());
 $('launch-boat').disabled=awaiting&&unpaid&&!affordable;
 $('launch-boat').onclick=()=>{if(s.launchStage==='stored'){const result=sim.launchBoat();if(!result.ok){feedback(result);txt('rental-message',result.message);return;}if(unpaid)audio.event('purchase');persist();closeModal();feedback(result);}else closeModal();feedback(sim.walkTo('boarding'));};
}
let inventoryView=null;
function openGear(tab='pack',filter='all',selectedId=null){
 const s=sim.state,layout=inventorySlots(s.profile,s.packed);
 const matches=g=>filter==='all'||(filter==='fishing'?['rod','reel','line','leader','rig','weight'].includes(g.slot):filter==='bait'?['bait','consumable'].includes(g.slot):!['rod','reel','line','leader','rig','weight','bait','consumable'].includes(g.slot));
 const items=tab==='shop'?GEAR_CATALOG.filter(g=>g.price>0&&matches(g)).map(g=>g.id):layout[tab]||layout.pack;
 const slots=tab==='shop'?[...items,...Array((6-items.length%6)%6).fill(null)]:items;
 inventoryView={tab,filter,slots,selected:Math.max(0,slots.indexOf(selectedId||slots.find(id=>id&&matches(GEAR_CATALOG.find(g=>g.id===id))))),moving:null};
 openModal('gear',`<span class="balance">✦ ${s.profile.credits}</span>`+heading('YOUR TACKLE BOX',tab==='shop'?'装备兑换':tab==='rig'?'鱼竿装配':'人物背包',`${s.profile.owned.length} 件物品 · 启用装备 ${sim.stats.weight.toFixed(1)} kg`)+`<div class="tabs gear-tabs">${[['pack','背包'],['rig','鱼竿'],['shop','商店']].map(([id,label])=>`<button data-tab="${id}" class="${id===tab?'active':''}">${label}</button>`).join('')}</div>`+(tab==='rig'?'<div id="rod-workbench"></div>':`<div class="inventory-layout"><div class="inventory-tray"><div class="inventory-toolbar"><span>${tab==='shop'?'货架':'个人物品'}</span><small id="slot-instruction">点击物品查看</small></div><div class="inventory-grid" role="group" aria-label="${tab==='shop'?'装备货架':'人物背包格子'}">${slots.map((id,index)=>{const g=GEAR_CATALOG.find(g=>g.id===id),visible=!g||matches(g),owned=g&&s.profile.owned.includes(id)&&g.slot!=='consumable';return`<button class="inventory-slot ${g?'filled':''} ${index===inventoryView.selected?'selected':''} ${visible?'':'filtered'}" data-slot="${index}" ${g?'draggable="true"':''} aria-label="格子 ${index+1}${g?'：'+esc(g.name):'：空'}" aria-pressed="${index===inventoryView.selected}">${g?`<canvas data-item-art="${id}" width="32" height="32" aria-hidden="true"></canvas><span class="slot-name">${esc(shortItemName(g))}</span>${tab==='shop'?`<span class="slot-count">${owned?'✓':'✦'+g.price}</span>`:g.id==='bait'?`<span class="slot-count">${Object.values(s.profile.stock).reduce((a,b)=>a+b,0)}</span>`:''}`:'<span class="slot-empty">·</span>'}</button>`;}).join('')}</div>${tab!=='shop'?`<div class="inventory-bottom"><span>${slots.filter(Boolean).length} / ${slots.length} 格</span><span>随时整理</span></div>`:''}</div><aside id="item-detail" class="item-detail" aria-live="polite"></aside></div>`));
 for(const el of document.querySelectorAll('[data-tab]'))el.onclick=()=>openGear(el.dataset.tab);
 if(tab==='rig'){mountRodWorkbench($('rod-workbench'),{sim,selectedRod:selectedId,onResult:feedback,onSave:()=>{persist();document.querySelector('#modal-content > .modal-desc').textContent=`${s.profile.owned.length} 件物品 · 启用装备 ${sim.stats.weight.toFixed(1)} kg`;},onSound:()=>audio.event('interaction')});return;}
 for(const canvas of document.querySelectorAll('[data-item-art]'))drawItemIcon(canvas,canvas.dataset.itemArt);
 for(const el of document.querySelectorAll('[data-slot]')){
  const index=Number(el.dataset.slot);
  el.onclick=()=>{if(inventoryView.moving!=null){const from=inventoryView.moving,id=slots[from];if(moveInventorySlot(s.profile,s.packed,tab,from,index)){audio.event('interaction');persist();openGear(tab,filter,id);}return;}inventoryView.selected=index;audio.event('interaction');renderItemDetail();};
  el.ondragstart=e=>{if(tab==='shop'||!slots[index]){e.preventDefault();return;}inventoryView.moving=index;e.dataTransfer.setData('text/plain',String(index));e.dataTransfer.effectAllowed='move';};
  el.ondragover=e=>{if(inventoryView.moving!=null){e.preventDefault();e.dataTransfer.dropEffect='move';}};
  el.ondrop=e=>{e.preventDefault();const from=inventoryView.moving;if(from==null)return;const id=slots[from];if(moveInventorySlot(s.profile,s.packed,tab,from,index)){persist();openGear(tab,filter,id);}};
  el.ondragend=()=>{if(inventoryView)inventoryView.moving=null;};
  el.onkeydown=e=>{const columns=getComputedStyle(el.parentElement).gridTemplateColumns.split(' ').length,delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-columns,ArrowDown:columns}[e.key];if(delta!=null){e.preventDefault();const next=Math.max(0,Math.min(slots.length-1,index+delta));document.querySelector(`[data-slot="${next}"]`)?.focus();}};
 }
 renderItemDetail();
}
function shortItemName(g){return({pfd:'救生衣',rod:'通用船竿',tackle:'单钩沉底',bait:'鱼饵盒',cooler:'冷藏箱',net:'抄网',descending_device:'降鱼器',water:'饮水用品',safety:'应急包',rod_light:'轻型船竿',rod_boat:'强韧船竿',reel_smooth:'泄力轮',line_braid:'编织线',leader_heavy:'耐磨前导',rig_slider:'滑铅组',rig_jig:'软饵组',rig_float:'浮游组',rig_dropper:'双支线组',rig_sabiki:'羽毛组',sinker_heavy:'铅坠包',bait_anchovy:'鳀鱼饵',bait_shrimp:'虾饵',bait_sardine:'沙丁鱼饵',bait_soft:'软饵',cooler_large:'大冷藏箱',nautical_chart:'纸海图',compass:'罗盘',gps:'GPS',sounder:'测深仪',anchor:'船锚',sea_anchor:'漂流伞'})[g.id]||g.name;}
function renderItemDetail(){
 const v=inventoryView,s=sim.state,id=v.slots[v.selected],g=GEAR_CATALOG.find(g=>g.id===id);
 for(const el of document.querySelectorAll('[data-slot]')){const selected=Number(el.dataset.slot)===v.selected;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));}
 if(!g){$('item-detail').innerHTML='<div class="empty-slot-detail">空格子<span>给下一次出海留一点位置。</span></div>';return;}
 const owned=s.profile.owned.includes(id)&&g.slot!=='consumable',packed=s.packed.includes(id),canChange=sim.state.fishState==='idle',atShop=sim.atCounter;
 $('item-detail').innerHTML=`<div class="item-detail-head"><canvas id="selected-item-art" width="32" height="32"></canvas><div><small>${{rod:'船竿',rig:'钓组',navigation:'导航仪器',electronics:'电子仪器',consumable:'消耗品',safety:'安全用品'}[g.slot]||'船上用品'}</small><h3>${esc(g.name)}</h3></div></div><p>${esc(g.id==='pfd'?'随身安全装备':g.desc)}</p><div class="item-facts"><span>${g.kg} kg</span>${g.hooks?`<span>${g.hooks} 钩</span>`:''}${g.capacity?`<span>${g.capacity} kg 容量</span>`:''}${v.tab==='shop'?`<b>✦ ${g.price}</b>`:''}</div>${g.id==='bait'?`<div class="bait-stock">${[['squid','鱿鱼'],['anchovy','鳀鱼'],['shrimp','虾'],['sardine','沙丁鱼'],['jig','软饵']].filter(([key])=>s.profile.stock[key]>0).map(([key,label])=>`<span>${label} × ${s.profile.stock[key]}</span>`).join('')}</div>`:''}<div class="item-actions">${v.tab==='shop'?`<button id="item-buy" class="primary" ${owned||!atShop?'disabled':''}>${owned?'已拥有':`兑换 · ${g.price}`}</button>${owned?`<button id="item-pack" class="secondary" ${!canChange||packed?'disabled':''}>${packed?'已启用':'启用装备'}</button>`:''}`:`<button id="item-pack" class="primary" ${!canChange?'disabled':''}>${packed?'收起装备':'启用装备'}</button>${g.slot==='rod'?'<button id="item-assemble" class="secondary">组装鱼竿</button>':''}<button id="item-move" class="secondary">移动格子</button>`}</div>${v.tab==='shop'&&!atShop?'<small class="item-location-note">到小屋柜台兑换；已有物品可随时整理。</small>':!canChange?'<small class="item-location-note">先收回水中的钓组，再调整装备。</small>':''}`;
 drawItemIcon($('selected-item-art'),g);
 if($('item-buy'))$('item-buy').onclick=()=>{const r=sim.buyGear(id);feedback(r);if(r.ok)audio.event('purchase');persist();openGear(v.tab,v.filter,id);};
 if($('item-pack'))$('item-pack').onclick=()=>{const r=sim.equip(id);feedback(r);persist();if(r.ok)openGear('pack','all',id);};
 if($('item-assemble'))$('item-assemble').onclick=()=>openGear('rig','all',id);
 if($('item-move'))$('item-move').onclick=()=>{v.moving=v.selected;txt('slot-instruction','再点一个格子，即可移动或交换');txt('item-move','取消移动');$('item-move').onclick=()=>{v.moving=null;txt('slot-instruction','点击物品查看');renderItemDetail();};};
}
function openMap(){const s=sim.state,nav=sim.navigationInstruments(),p=s.mode==='walk'?{x:s.playerX,z:s.playerZ}:{x:s.boatX,z:s.boatZ};if(!nav.chart){openModal('map',heading('THE UNCHARTED MORNING','背包里还没有海图')+`<div class="instrument-empty">⌖</div><p class="modal-desc">在码头小屋兑换纸质海图，再从个人背包启用。</p><div class="button-row">${button('chart-shop','查看装备',true)}</div>`);$('chart-shop').onclick=()=>openGear('shop','other');return;}const range=spot=>nav.gps?`${(compressedDistance(p,spot)/1000).toFixed(2)} km →`:'→';openModal('map',heading('MONTEREY BAY','折起的海图',`航程比例 1:2 · ${nav.gps?'GPS 已连接':'纸图不显示当前位置'}`)+`<canvas id="chart" class="map-canvas" width="540" height="240" aria-label="Santa Cruz 海岸与钓点"></canvas><div class="spot-list">${FISHING_SPOTS.map((spot,i)=>`<button class="spot-button" data-spot="${i}"><div><strong>${i+1}. ${spot.name}</strong><small>${{sand:'沙底',kelp:'海带林',reef:'岩礁'}[spot.kind]}</small></div><span>${range(spot)}</span></button>`).join('')}<button id="return-dock" class="spot-button"><div><strong>↩ 返回码头小屋</strong><small>靠泊 · 兑换 · 补给</small></div><span>${range({x:HARBOR.returnX,z:HARBOR.returnZ})}</span></button></div><p class="credits-note">海岸轮廓 © OpenStreetMap contributors。地理坐标保留；外海航程压缩，近码头恢复原比例。</p>`);drawChart();for(const el of document.querySelectorAll('[data-spot]'))el.onclick=()=>{const target=FISHING_SPOTS[Number(el.dataset.spot)];closeModal();feedback(sim.selectWaypoint(target));};$('return-dock').onclick=()=>{closeModal();feedback(sim.state.mode==='walk'?sim.walkTo('counter'):sim.selectWaypoint('dock'));};}
function drawChart(){const c=$('chart'),ctx=c.getContext('2d'),W=c.width,H=c.height;const bounds={minX:-2400,maxX:3900,minZ:-2200,maxZ:900},sx=W/(bounds.maxX-bounds.minX),sz=H/(bounds.maxZ-bounds.minZ),pt=(x,z)=>[(x-bounds.minX)*sx,(z-bounds.minZ)*sz];ctx.fillStyle='#32858a';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#9bd0bd22';ctx.lineWidth=1;for(let x=0;x<W;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<H;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}for(const rings of[landPolygons,pierRings])for(const ring of rings){ctx.beginPath();ring.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](...pt(p.x,p.z)));ctx.closePath();ctx.fillStyle=rings===pierRings?'#bc8867':'#d2ce9d';ctx.fill();}ctx.font='10px monospace';for(const [i,p]of FISHING_SPOTS.entries()){const[x,y]=pt(p.x,p.z);ctx.fillStyle='#fff1d5';ctx.fillRect(x-4,y-4,8,8);ctx.fillText(String(i+1),x+9,y+4);}const s=sim.state,pos=s.mode==='walk'?{x:s.playerX,z:s.playerZ}:{x:s.boatX,z:s.boatZ},[x,y]=pt(pos.x,pos.z);if(sim.navigationInstruments().gps){ctx.fillStyle='#f08d6d';ctx.fillRect(x-4,y-4,8,8);ctx.fillStyle='#fff1d5';ctx.fillText('YOU',x+9,y-3);}ctx.fillStyle='#fff1d5';ctx.fillText('SANTA CRUZ',20,23);ctx.fillStyle='#a6d4c4';ctx.fillText('MONTEREY BAY',W-115,H-17);}
function fishSprite(f){return sprites.fish[f?.name?.includes('比目')?'halibut':f?.name?.includes('鲭')?'mackerel':f?.name?.includes('单线')?'lingcod':'rockfish'];}
function openCatch(){const f=sim.state.fish;if(!f)return;openModal('catch',heading('A MOMENT TO REMEMBER',esc(f.name),esc(f.latin))+`<div class="catch-hero"><canvas id="catch-art"></canvas></div><div class="catch-stats"><div><strong>${f.length}</strong><small>厘米</small></div><div><strong>${f.kg}</strong><small>千克</small></div><div><strong>${Math.round(sim.state.fightTime)}</strong><small>搏鱼秒数</small></div></div><div class="button-row">${button('keep-fish','收入冰箱',true)}${button('release-fish','记录并放流')}</div>`);drawAsset($('catch-art'),fishSprite(f));$('keep-fish').onclick=()=>{const r=sim.keepCatch();feedback(r);if(r.ok){closeModal();persist();}};$('release-fish').onclick=()=>{feedback(sim.releaseCatch());closeModal();persist();};}
function openJournal(){const s=sim.state;openModal('journal',`<span class="balance">✦ ${s.profile.credits}</span>`+heading('THE DAYS WE KEEP','鱼获与航程',`抛竿 ${s.casts} 次 · 鱼获 ${s.catches.length} 条`)+(s.catches.length?s.catches.slice().reverse().map((f,i)=>`<div class="catch-row"><canvas id="journal-fish-${i}"></canvas><div><b>${esc(f.name)}</b><small>${f.length} cm · ${f.kg} kg · ${f.time}</small></div><span>${f.confiscated?'已没收':f.settled?'已记录':f.kept?'冰箱中':'已放流'}</span></div>`).join(''):'<p class="journal-empty">冰箱里还很安静。<br>好故事，总会从第一竿开始。</p>')+`<h3>航海手记</h3><div class="key-list">${s.journal.slice(0,10).map(j=>`${j.time}　${esc(j.text)}`).join('<br>')}</div>`);s.catches.slice().reverse().forEach((f,i)=>drawAsset($(`journal-fish-${i}`),fishSprite(f)));}
function openSettings(){const m=marineSummary();openModal('settings',heading('SLOW DOWN, CAST OUT','海风与设置')+`<div class="settings-grid">${button('settings-audio',`总声音：${audio.enabled?'开':'关'}`)}${button('settings-music',`轻快背景音乐：${audio.musicEnabled?'开':'关'}`)}${button('settings-photo','保存像素风景')}${started?button('settings-rescue','呼叫免费救援'):''}</div><div class="form-row"><label for="music-volume">音乐音量</label><input id="music-volume" type="range" min="0" max="1" step=".01" value="${audio.musicVolume}"></div><h3>操作</h3><p class="key-list">移动：左下摇杆 / WASD<br>操船：摆动握把转向，上下划动旋转油门<br>先收油再换挡；N 回空挡。松手保留握把与油门位置<br>WASD 也可操船，键盘松手收油<br>船边下放：点下放 / 空格；可选抛投：按住抛投、松开<br>竿姿：上下拖动抬竿，左右拖动摆竿<br>摇轮：顺时针转鱼轮，或按住轮柄 / F<br>打开线杯放线，锁住线杯停放；✳ 泄力上下拖动调整<br>E 互动 · Q 锚 · R 引擎 · I 装备 · M 海图<br>轻提：调整竿姿 / 按住空格；摇轮将钓组收至船边<br>选择左/右舷竿架可慢速拖钓；咬钩后取竿<br>携带海图后，点击水面可设置辅助航向。</p><h3>今天的海</h3><p class="credits-note">${m.label} · 风 ${sea.windKnots.toFixed(1)} kn · 浪 ${sea.waveHeight.toFixed(1)} m · 海温 ${sea.waterTemp.toFixed(1)} °C<br>观测时间：${m.observedAt?new Date(m.observedAt).toLocaleString('zh-CN',{timeZone:'America/Los_Angeles'}):'暂不可用'}（Santa Cruz）<br>区域浮标距离约 23–40 km，非船边实测。<br>每次出发从 06:00 开始，游戏时间 2 倍速；外海航程比例 1:2。打开菜单时暂停。</p><p class="credits-note">原创 Canvas 像素美术 · 海岸数据 <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap</a> · <a href="https://www.ndbc.noaa.gov/station_page.php?station=46236" target="_blank" rel="noopener">NOAA 海况</a>。人物为虚构值班员。鱼获交易使用游戏积分。</p><details class="source-details"><summary>资料来源与模拟说明</summary><p class="credits-note">鱼种、水域与钓法参考 CDFW、NOAA 和 California Sea Grant。鱼讯、生态出现及巡查概率为游戏参数，并非实测概率。法规使用核实于 2026-09-27 的 2026 年快照，未知证据不判为违规。</p><p class="credits-note"><a href="https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary" target="_blank" rel="noopener">CDFW 底栖鱼规定</a> · <a href="https://wildlife.ca.gov/Fishing/Ocean/Regulations/Fishing-Map/San-Francisco" target="_blank" rel="noopener">Point Sur 以北比目鱼规定</a> · <a href="https://montereybay.noaa.gov/visitor/seasons.html" target="_blank" rel="noopener">NOAA 季节生态</a></p></details>`);$('settings-audio').onclick=()=>{audio.init();audio.toggle();openSettings();};$('settings-music').onclick=()=>{audio.init();audio.toggleMusic();openSettings();};$('music-volume').oninput=()=>{audio.init();audio.setMusicVolume(Number($('music-volume').value));};$('settings-photo').onclick=()=>{closeModal();const a=document.createElement('a');a.href=$('world').toDataURL('image/png');a.download='santa-cruz-pixel.png';a.click();};if($('settings-rescue'))$('settings-rescue').onclick=()=>{closeModal();feedback(sim.rescue());persist();};}
function openActions(){const s=sim.state;openModal('actions',heading('ABOARD YOUR SKIFF','船上时光')+`<div class="settings-grid">${button('action-stand',s.standing?'坐回驾驶座':'站起来活动')}${button('action-rig','鱼竿装配')}${sim.navigationInstruments().sounder?button('action-sounder','查看测深仪'):''}${sim.navigationInstruments().gps?button('action-gps','查看 GPS'):''}${button('action-return','返航')}${button('action-retrieve','鱼轮控制')}</div>`);$('action-stand').onclick=()=>{closeModal();feedback(sim.stand());};$('action-rig').onclick=()=>openGear('rig');if($('action-sounder'))$('action-sounder').onclick=openSounder;if($('action-gps'))$('action-gps').onclick=openGPS;$('action-return').onclick=()=>{closeModal();feedback(sim.selectWaypoint('dock'));};$('action-retrieve').onclick=()=>{closeModal();boatPanel='tackle';reelToggle=false;updateUI();};}
function openGPS(){const n=sim.navigationInstruments();if(!n.gps)return;const p=n.gpsPosition;openModal('gps',heading('GPS RECEIVER','当前位置')+`<div class="gps-reading">${p.lat.toFixed(5)}° N<br>${Math.abs(p.lon).toFixed(5)}° W</div><p class="modal-desc">航速 ${Math.abs(sim.state.speed*1.94384).toFixed(1)} kn</p><p class="credits-note">地理坐标保留真实尺度。游戏外海航程采用 1:2 比例。</p>`);}
function openSounder(){if(!sim.navigationInstruments().sounder)return;const s=sim.state;openModal('sounder',heading('BOTTOM PROFILE','船下的起伏','沿船首方向前后各 50 m · NOAA 地形参考')+`<canvas id="sounder-chart" class="map-canvas" width="540" height="240"></canvas><p class="credits-note">历史 MHW 地形网格约 20.7 m 分辨率；空缺表示没有参考数据。</p>`);const c=$('sounder-chart'),x=c.getContext('2d'),samples=Array.from({length:81},(_,i)=>{const d=(i-40)*1.25;return depthInfoAt(s.boatX-Math.sin(s.heading)*d,s.boatZ-Math.cos(s.heading)*d).value;}),valid=samples.filter(Number.isFinite),max=Math.max(12,...valid)*1.2;x.fillStyle='#245f70';x.fillRect(0,0,540,240);x.strokeStyle='#bccc98';x.lineWidth=2;let previous=null;for(let i=0;i<samples.length;i++){const d=samples[i];if(!Number.isFinite(d)){previous=null;continue;}const px=20+i*6.25,py=30+d/max*180;if(previous){x.fillStyle='#a2a47b';x.beginPath();x.moveTo(previous.x,previous.y);x.lineTo(px,py);x.lineTo(px,220);x.lineTo(previous.x,220);x.closePath();x.fill();x.beginPath();x.moveTo(previous.x,previous.y);x.lineTo(px,py);x.stroke();}previous={x:px,y:py};}x.fillStyle='#fff1d5';x.font='12px monospace';x.fillText('-50 m',20,17);x.fillText('BOAT',253,17);x.fillText('+50 m',475,17);x.fillText(Number.isFinite(samples[40])?`${samples[40].toFixed(1)} m`:'—',279,40);x.setLineDash([3,3]);x.strokeStyle='#fff1d5';x.beginPath();x.moveTo(270,25);x.lineTo(270,217);x.stroke();}
