function castDown(source,explicitCast=false){if(menu)return false;const s=sim.state;if(s.fishState==='landed'){openCatch();return false;}if(s.fishState==='bite'){feedback(sim.hook());return false;}if(['fight','sinking','waiting'].includes(s.fishState)){sources.set('pump',source,true);return true;}const r=explicitCast?sim.startCast():sim.lowerRig();feedback(r);if(r.action==='casting'){castOwner=source;}return r.ok;}
function castUp(source,cancel=false){sources.set('pump',source,false);if(sim.state.casting&&castOwner===source){castOwner=null;feedback(cancel?sim.cancelCast():sim.releaseCast());}}
function stickMove(e){const r=$('joystick').getBoundingClientRect();stick=stickVector(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2,r.width*.4);$('stick-thumb').style.transform=`translate(${stick.x*r.width*.3}px,${stick.y*r.height*.3}px)`;}
function stickEnd(){stick={x:0,y:0};$('stick-thumb').style.transform='';if(stickDriving&&sim.state.engine&&!sim.state.waypoint)sim.setThrottle(0);stickDriving=false;}
