window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if(menu){if(e.key==='Tab'){const focusable=[...$('modal').querySelectorAll('button:not(:disabled),select,input,a[href]')].filter(el=>!el.hidden);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(!started||e.target.closest?.('select,input,textarea,[role=slider]'))return;const k=e.key.toLowerCase();if(e.target.closest?.('button')&&[' ','enter'].includes(k))return;if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','f'].includes(k))e.preventDefault();if(e.repeat)return;keys.add(k);if(k===' ')castDown('keyboard');if(k==='f')sources.set('reel','keyboard',true);if(k==='e')feedback(sim.interact());if(k==='q')feedback(sim.toggleAnchor());if(k==='r')$('engine-btn').click();if(k==='i')openGear();if(k==='m')openMap();if(k==='j')openJournal();if(k==='g')$('guide-btn').click();});
