function input(dt){const x=stick.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),z=stick.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0),s=sim.state,rodInput=fishing.input(dt),result={moveX:x,moveZ:z,steer:-x,reel:Math.max(rodInput.reel,(reelToggle||sources.sources.get('reel')?.size>0)?1.2:0),pump:sources.sources.get('pump')?.size>0};if(s.mode==='boat'&&!s.standing&&(Math.abs(z)>.05||Math.abs(x)>.05)&&s.engine&&sim.canOperateHelm){result.throttle=Math.max(-.3,-z);stickDriving=true;helm.reset();result.throttle=Math.max(-.3,-z);}else if(s.mode==='boat'&&!s.standing&&s.engine&&sim.canOperateHelm)Object.assign(result,helm.input());return result;}
